        jdbc.update("UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = ?", sheetId);
        return jdbc.queryForObject("SELECT last_claim_number FROM sheet WHERE id = ?", Integer.class, sheetId);
    }
}
